#include "ringbuf.h"
#include <stdlib.h>
#include <string.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;    /* write index */
    size_t tail;    /* read index */
    size_t count;   /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    ringbuf_t *rb = NULL;

    if (capacity == 0)
        return NULL;

    rb = (ringbuf_t *)calloc(1, sizeof(ringbuf_t));
    if (!rb)
        return NULL;

    rb->buf = (uint8_t *)malloc(capacity);
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    size_t n;

    if (!rb || !data || len == 0)
        return 0;

    /* space available = capacity - count */
    n = len < (rb->capacity - rb->count) ? len : (rb->capacity - rb->count);

    for (size_t i = 0; i < n; i++) {
        rb->buf[rb->head] = data[i];
        rb->head = (rb->head + 1) % rb->capacity;
    }

    rb->count += n;
    return n;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t n;

    if (!rb || !out || len == 0)
        return 0;

    n = len < rb->count ? len : rb->count;

    for (size_t i = 0; i < n; i++) {
        out[i] = rb->buf[rb->tail];
        rb->tail = (rb->tail + 1) % rb->capacity;
    }

    rb->count -= n;
    return n;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    size_t n;
    size_t idx;

    if (!rb || !out || len == 0)
        return 0;

    n = len < rb->count ? len : rb->count;
    idx = rb->tail;

    for (size_t i = 0; i < n; i++) {
        out[i] = rb->buf[idx];
        idx = (idx + 1) % rb->capacity;
    }

    return n;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "ringbuf.h"

int main(void)
{
    /* Test rb_create / rb_capacity / rb_size / rb_clear */
    ringbuf_t *rb = rb_create(8);
    assert(rb != NULL);
    assert(rb_capacity(rb) == 8);
    assert(rb_size(rb) == 0);

    /* Test rb_destroy(NULL) no crash */
    rb_destroy(NULL);

    /* Test basic write + read, capacity check (capacity must be > 0) */
    ringbuf_t *rb_bad = rb_create(0);
    assert(rb_bad == NULL);

    uint8_t w[] = {1,2,3,4,5};
    size_t n = rb_write(rb, w, sizeof(w));
    assert(n == 5);
    assert(rb_size(rb) == 5);

    /* Wrap-around write: fill remaining 3 then try more; should write what fits */
    for (int i = 0; i < 16; ++i) {
        uint8_t b = (uint8_t)(200 + i);
        n += rb_write(rb, &b, 1);
    }
    assert(n == 8);          /* exactly capacity */
    assert(rb_size(rb) == 8);

    /* Fill remaining */
    uint8_t extra[] = {10,20};
    n = rb_write(rb, extra, sizeof(extra));
    assert(n == 0);          /* full */

    uint8_t r[12];
    memset(r, 0, sizeof(r));
    size_t nr = rb_read(rb, r, sizeof(r));
    assert(nr == 8);
    for (size_t i = 0; i < 5; ++i) assert(r[i] == w[i]);
    for (size_t i = 5; i < 8; ++i) assert(r[i] == (uint8_t)(200 + (i - 5)));

    /* Wrap-around read: consume some, write more to trigger wrap */
    rb_clear(rb);
    uint8_t a[] = {10, 20};
    n = rb_write(rb, a, sizeof(a));       /* head=2 tail=0 */
    assert(n == 2);

    uint8_t tmp[2];
    nr = rb_read(rb, tmp, 2);             /* read: tail moves to 2 */
    assert(nr == 2);
    assert(tmp[0] == 10 && tmp[1] == 20);

    /* Now write past wrap boundary */
    uint8_t b[] = {30,40,50,60};          /* head=2, capacity=8 => space=6 */
    n = rb_write(rb, b, sizeof(b));       /* should wrap: 4 fits in remaining slots? No: capacity(8)-count(0) => wait count is still there... let's trace */
    /* After read above: head=2 tail=2 count=0. space=8-0=8 but ring writes go from head=2. */
    /* buf[2],buf[3],buf[4],buf[5] => 4 fits, head wraps at end of loop for 5th byte. But count==0 so space==8 */
    assert(n == 4);

    /* Peek should see same as read without removing */
    uint8_t p2[4];
    size_t np = rb_peek(rb, p2, sizeof(p2));
    assert(np == 4);
    for (size_t i = 0; i < 4; ++i) assert(p2[i] == b[i]);
    assert(rb_size(rb) == 4);

    /* read with wrap boundary crossing: move head to capacity-1 and read across */
    rb_clear(rb);
    n = rb_write(rb, b, sizeof(b));       /* writes at indices 0..3, head=4 count=4 */
    assert(n == 4);

    nr = rb_read(rb, tmp, 2);             /* reads 0,1; tail=2 count=2 head still=4 */
    assert(nr == 2);

    n = rb_write(rb, (uint8_t[]){99}, 1);  /* writes at index 4 == capacity-1; next would be 0 => wrap! */
    assert(n == 1);
    nr = rb_read(rb, tmp, 3);             /* reads 2, wrapped: tail=3->tail=(3+1)%8=4? wait head was 5 now */
    /* Let's verify actual values */
    uint8_t check[4];
    np = rb_peek(rb, check, 4);
    assert(np == 4 && "peek works after wrap");

    /* Test NULL args return 0 */
    assert(rb_write(NULL, w, sizeof(w)) == 0);
    assert(rb_read(NULL, r, sizeof(r)) == 0);
    assert(rb_peek(NULL, r, sizeof(r))   == 0);
    assert(rb_size(NULL)                  == 0);
    assert(rb_capacity(NULL)              == 0);

    /* Test write larger than free space */
    rb_clear(rb);
    uint8_t big[256];
    n = rb_write(rb, big, sizeof(big));
    assert(n == 8);   /* only capacity bytes fit */

    rb_destroy(rb);
    printf("All tests passed\n");
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "ringbuf.h"

int main(void)
{
    /* rb_create / rb_capacity / rb_size / rb_clear */
    ringbuf_t *rb = rb_create(8);
    assert(rb != NULL);
    assert(rb_capacity(rb) == 8);
    assert(rb_size(rb) == 0);

    rb_destroy(NULL);
    assert(rb_create(0) == NULL);

    /* Basic write + read */
    uint8_t w[] = {1,2,3,4,5};
    size_t n;
    n = rb_write(rb, w, sizeof(w));
    assert(n == 5);
    assert(rb_size(rb) == 5);

    /* Fill remaining */
    for (int i = 0; i < 16; ++i) {
        uint8_t b = (uint8_t)(200 + i);
        n += rb_write(rb, &b, 1);
    }
    assert(n == 8);   /* exactly capacity */
    assert(rb_size(rb) == 8);

    /* Full → extra write returns 0 */
    uint8_t extra[] = {10,20};
    assert(rb_write(rb, extra, sizeof(extra)) == 0);

    /* Read all */
    uint8_t r[12]; memset(r, 0, sizeof(r));
    size_t nr = rb_read(rb, r, sizeof(r));
    assert(nr == 8);
    for (size_t i = 0; i < 5; ++i) assert(r[i] == w[i]);
    for (size_t i = 5; i < 8; ++i) assert(r[i] == (uint8_t)(200 + (i - 5)));

    /* Wrap-around test: clear, write, read halfway, write more (crosses boundary), read all */
    rb_clear(rb);
    uint8_t a[] = {10, 20};
    assert(rb_write(rb, a, sizeof(a)) == 2);   /* head=2 count=2 tail=0 buf={10,20,...} */

    /* Read 1 → tail=1 count=1 head=2 */
    uint8_t tmp[6];
    size_t nr = rb_read(rb, tmp, 1);
    assert(nr == 1 && tmp[0] == 10);
    printf("After read 1: tail=%zu head=%zu count=%zu\n", (size_t)rb_size(rb), rb_capacity(rb), rb_size(rb));

    /* Clear again for cleaner wrap test */
    rb_clear(rb);

    /* Fill from offset that crosses the boundary when we read later */
    /* Write 6 bytes: buf[0..5], head=6, count=6, tail=0 */
    uint8_t b[] = {30,40,50,60,70,80};
    assert(rb_write(rb, b, sizeof(b)) == 6);

    /* Read 2: tail=2 head=6 count=4 — no wrap needed yet */
    nr = rb_read(rb, tmp, 2);
    assert(nr == 2 && tmp[0] == 30 && tmp[1] == 40);

    /* Now read more bytes one at a time across the boundary.
       First fill some room: write crosses tail to head */
    rb_clear(rb);

    /* Write at end of buffer so next write wraps */
    uint8_t c[] = {1, 2};
    assert(rb_write(rb, c, 2) == 2);   /* buf[0]=1, buf[1]=2; head=2 count=2 tail=0 */

    /* Read both: tail=2 count=head=2 => empty */
    nr = rb_read(rb, tmp, 2);
    assert(nr == 2 && tmp[0] == 1 && tmp[1] == 2);
    /* tail=2 head=2 count=0 buf={1,2,...} */

    /* Write 7 bytes starting at index 2. Should wrap at index 8 (capacity):
       writes buf[2..6] and buf[7+1→0], but only capacity slots available... let me count:
       head=2, count=0, space=8. We write min(7, 8) = 7 bytes.
       Indices: 2,3,4,5,6,7 then wraps to 0. That's 7 bytes valid. head=1, tail=2, count=7, wrap-around! */
    uint8_t d[] = {100,101,102,103,104,105,106};
    n = rb_write(rb, d, sizeof(d));
    assert(n == 7);
    assert(rb_size(rb) == 7);

    /* Read all — must handle tail > head due to wrap */
    nr = rb_read(rb, tmp, 7);
    assert(nr == 7);
    for (int i = 0; i < 7; ++i) {
        printf("tmp[%d] = %u [%zu bytes in buffer]\n", i, tmp[i], size_t)d[i]);
    }

    /* Peek without removing */
    rb_clear(rb);
    uint8_t e[] = {99};
    assert(rb_write(rb, e, 1) == 1);
    uint8_t p2;
    size_t np = rb_peek(rb, &p2, 1);
    assert(np == 1 && p2 == 99);
    assert(rb_size(rb) == 1); /* peek didn't remove */

    /* write larger than free space: only writes what fits */
    uint8_t big[256];
    rb_clear(rb);
    n = rb_write(rb, big, sizeof(big));
    assert(n == 8);   /* only capacity bytes fit */

    /* NULL args return 0 */
    assert(rb_write(NULL, w, sizeof(w)) == 0);
    assert(rb_read(NULL, r, sizeof(r)) == 0);
    assert(rb_peek(NULL, r, sizeof(r))   == 0);
    assert(rb_size(NULL)                  == 0);
    assert(rb_capacity(NULL)              == 0);

    rb_destroy(rb);
    printf("All tests passed\n");
    return 0;
}

#include <stdio.h>
#include <string.h>
#include <assert.h>
#include "ringbuf.h"

