    /* Write 6 bytes: head=6, count=6, tail=0 */
    uint8_t b[] = {30,40,50,60,70,80};
    n = rb_write(rb, b, sizeof(b));
    assert(n == 6);

    /* Read 2: tail=2, count=4 */
    uint8_t tmp[10];
    size_t nr = rb_read(rb, tmp, 2);
    assert(nr == 2 && tmp[0] == 30 && tmp[1] == 40);

